export interface LitCity {
  lat: number;
  lon: number;
  /** Lit weight, roughly millions of people × electrification. */
  w: number;
}

let cache: LitCity[] | null = null;

export function litCities(): LitCity[] {
  if (cache) return cache;
  const out: LitCity[] = [];
  for (const [factor, data] of BLOCKS) {
    for (const entry of data.split(";")) {
      const parts = entry.trim().split(/\s+/);
      if (parts.length < 3) continue;
      const lat = Number(parts[0]);
      const lon = Number(parts[1]);
      const w = Number(parts[2]) * factor;
      if (Number.isFinite(lat) && Number.isFinite(lon) && w > 0) out.push({ lat, lon, w });
    }
  }
  cache = out;
  return out;
}

